const textInput=document.getElementById("text-input"),outputArea=document.getElementById("output-area"),copyBtn=document.getElementById("copy-btn"),clearBtn=document.getElementById("clear-btn");function copyToClipboard(e,t){navigator.clipboard.writeText(e).then(()=>{const e=t.textContent;t.textContent="Copied!",setTimeout(()=>{t.textContent=e},2e3)}).catch(()=>{t.textContent="Failed",setTimeout(()=>{t.textContent="Copy Result"},2e3)})}function convertCase(e){const t=textInput.value;if(!t.trim())return void(outputArea.textContent="Please enter some text to convert.");let o="";switch(e){case"upper":o=t.toUpperCase();break;case"lower":o=t.toLowerCase();break;case"title":o=t.toLowerCase().replace(/\b\w/g,e=>e.toUpperCase());break;case"sentence":o=t.toLowerCase().replace(/(^\w|\.\s+\w)/g,e=>e.toUpperCase());break;case"camel":o=t.toLowerCase().replace(/(?:^\w|[A-Z]|\b\w)/g,(e,t)=>0===t?e.toLowerCase():e.toUpperCase()).replace(/\s+/g,"");break;case"pascal":o=t.toLowerCase().replace(/(?:^\w|[A-Z]|\b\w)/g,e=>e.toUpperCase()).replace(/\s+/g,"");break;case"snake":o=t.toLowerCase().replace(/\s+/g,"_").replace(/[^\w_]/g,"");break;case"kebab":o=t.toLowerCase().replace(/\s+/g,"-").replace(/[^\w-]/g,"");break;case"toggle":o=t.split("").map(e=>e===e.toUpperCase()?e.toLowerCase():e.toUpperCase()).join("");break;default:o=t}outputArea.textContent=o}copyBtn.addEventListener("click",()=>{copyToClipboard(outputArea.textContent,copyBtn)}),clearBtn.addEventListener("click",()=>{textInput.value="",outputArea.textContent="Your converted text will appear here..."}),document.getElementById("back-to-tools-btn").addEventListener("click",function(e){e.preventDefault(),window.location.href="/#utility-tools-section"});